<?php
declare(strict_types=1);require '../config/db.php';require '../config/auth.php';require_role('parishioner','login.php');$u=current_user();$id=(int)($_GET['id']??0);$s=$pdo->prepare("SELECT a.*,s.name service_name,s.description service_description,r.name resource_name FROM appointments a JOIN services s ON s.id=a.service_id LEFT JOIN resources r ON r.id=a.resource_id WHERE a.id=? AND a.user_id=?");$s->execute([$id,$u['id']]);$a=$s->fetch();if(!$a){http_response_code(404);exit('Appointment not found.');}$s=$pdo->prepare("SELECT h.*,u.full_name changed_by_name FROM appointment_history h LEFT JOIN users u ON u.id=h.changed_by WHERE h.appointment_id=? ORDER BY h.created_at DESC");$s->execute([$id]);$history=$s->fetchAll();$pageTitle='Appointment details.';$eyebrow=$a['reference_no'];?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Appointment Details</title><link rel="stylesheet" href="../assets/css/style.css"></head><body><div class="shell"><?php include 'includes/sidebar.php'?><main class="main"><?php include 'includes/header.php'?><section class="grid two"><div class="card"><h2><?=e($a['service_name'])?></h2><p class="muted"><?=e($a['service_description'])?></p><div class="grid two"><div><small class="muted">Reference</small><p><b><?=e($a['reference_no'])?></b></p><small class="muted">Date</small><p><?=date('F j, Y',strtotime($a['appointment_date']))?></p><small class="muted">Time</small><p><?=date('g:i A',strtotime($a['start_time']))?> – <?=date('g:i A',strtotime($a['end_time']))?></p></div><div><small class="muted">Status</small><p><span class="badge <?=e($a['status'])?>"><?=e($a['status'])?></span></p><small class="muted">Resource</small><p><?=e($a['resource_name']??'Not assigned')?></p><small class="muted">Submitted</small><p><?=date('M j, Y g:i A',strtotime($a['created_at']))?></p></div></div><hr style="border:0;border-top:1px solid var(--line)"><small class="muted">Payment</small><p><b><?=ucfirst(e($a['payment_method']??'cash'))?></b> · <?=e(str_replace('_',' ',$a['payment_status']??'not_required'))?></p><?php if(($a['payment_method']??'')==='online'&&($a['payment_status']??'')==='pending'):?><div class="notice">Your payment receipt is waiting for admin verification.</div><?php endif?><?php if(in_array($a['status'],['approved','completed'],true)):?><div class="appointment-qr-card"><div class="eyebrow">Approved appointment pass</div><h2>Present this QR / reference</h2><img class="appointment-qr" src="https://api.qrserver.com/v1/create-qr-code/?size=220x220&amp;data=<?=rawurlencode($a['reference_no'])?>" alt="Appointment QR for <?=e($a['reference_no'])?>"><div class="qr-reference"><?=e($a['reference_no'])?></div><div class="notice"><b>Save this QR code.</b><br>Take a screenshot or save this page, then present the QR code and reference number to the parish administrator on your appointment date for confirmation.</div></div><?php endif?><?php if($a['notes']):?><hr style="border:0;border-top:1px solid var(--line)"><small class="muted">Your notes</small><p><?=nl2br(e($a['notes']))?></p><?php endif?><?php if($a['admin_note']):?><div class="notice <?= $a['status']==='rejected' ? 'error' : '' ?>"><b><?= $a['status']==='rejected' ? 'Reason for rejection' : 'Parish office note' ?></b><br><?=nl2br(e($a['admin_note']))?><?php if($a['status']==='rejected'):?><br><br><span class="muted">You may book another available schedule from Book Service.</span><?php endif?></div><?php endif?><div class="actions"><a class="btn light" href="my-appointments.php">← Back</a><button class="btn" onclick="window.print()">Print slip</button></div></div><div class="card"><h2>Status timeline</h2><div class="timeline"><?php foreach($history as $h):?><div class="timeline-item"><b><?=ucfirst(e($h['status']))?></b><div class="muted" style="font-size:12px"><?=date('M j, Y · g:i A',strtotime($h['created_at']))?></div><?php if($h['note']):?><p><?=e($h['note'])?></p><?php endif?></div><?php endforeach?></div></div></section></main></div><script src="../assets/js/script.js"></script></body></html>
